"use client";

import {
  useEffect,
  useId,
  useRef,
  useState,
} from "react";

import { createPortal } from "react-dom";

import {
  ArrowRight,
  SlidersHorizontal,
  X,
} from "lucide-react";

import {
  CatalogSidebar,
  type CatalogFilterOption,
  type CatalogFilterValues,
  type CatalogPriceBounds,
} from "@/components/catalog/CatalogSidebar";

import type { SiteLocale } from "@/lib/site-i18n";

// ============================================================
// CYCLORIVA — FILTRES DU CATALOGUE MOBILE
// ============================================================
//
// Next.js 16 — React — TypeScript — Tailwind CSS 4
//
// Architecture :
// - Bouton Filtres (nombre de filtres actifs)
// - Panneau coulissant mobile
// - Fond assombri
// - Catégories
// - Prix minimum / maximum
// - Marques
// - Disponibilité
// - Réinitialisation
// - Bouton Voir les produits
//
// Réutilise CatalogSidebar en mode "mobile".
//
// Aucun produit, prix ou stock fictif.
//
// ============================================================

// ============================================================
// TYPES
// ============================================================

export type CatalogMobileFiltersProps = {
  locale: SiteLocale;

  filters: CatalogFilterValues;

  onChange: (
    filters: CatalogFilterValues
  ) => void;

  categories: CatalogFilterOption[];
  brands: CatalogFilterOption[];
  availability: CatalogFilterOption[];

  priceBounds: CatalogPriceBounds;

  resultCount?: number;

  className?: string;

  open?: boolean;
  onOpenChange?: (open: boolean) => void;

  showTrigger?: boolean;
};

// ============================================================
// TRADUCTIONS
// ============================================================

type MobileFiltersText = {
  filters: string;
  close: string;
  reset: string;
  showProducts: string;
  showProduct: string;
  activeFilters: string;
  noActiveFilters: string;
};

const translations: Record<
  SiteLocale,
  MobileFiltersText
> = {
  fr: {
    filters: "Filtres",
    close: "Fermer les filtres",
    reset: "Tout effacer",
    showProducts: "Voir les produits",
    showProduct: "Voir le produit",
    activeFilters: "filtres actifs",
    noActiveFilters: "Aucun filtre actif",
  },

  en: {
    filters: "Filters",
    close: "Close filters",
    reset: "Clear all",
    showProducts: "View products",
    showProduct: "View product",
    activeFilters: "active filters",
    noActiveFilters: "No active filters",
  },

  de: {
    filters: "Filter",
    close: "Filter schließen",
    reset: "Alle löschen",
    showProducts: "Produkte anzeigen",
    showProduct: "Produkt anzeigen",
    activeFilters: "aktive Filter",
    noActiveFilters: "Keine aktiven Filter",
  },

  it: {
    filters: "Filtri",
    close: "Chiudi filtri",
    reset: "Cancella tutto",
    showProducts: "Mostra prodotti",
    showProduct: "Mostra prodotto",
    activeFilters: "filtri attivi",
    noActiveFilters: "Nessun filtro attivo",
  },

  es: {
    filters: "Filtros",
    close: "Cerrar filtros",
    reset: "Borrar todo",
    showProducts: "Ver productos",
    showProduct: "Ver producto",
    activeFilters: "filtros activos",
    noActiveFilters: "No hay filtros activos",
  },
};

// ============================================================
// UTILITAIRES
// ============================================================

function countActiveFilters(
  filters: CatalogFilterValues
): number {
  let count = 0;

  count += filters.categories.length;
  count += filters.brands.length;
  count += filters.availability.length;

  if (filters.minPrice !== null) {
    count += 1;
  }

  if (filters.maxPrice !== null) {
    count += 1;
  }

  return count;
}

function formatCount(
  value: number,
  locale: SiteLocale
): string {
  return new Intl.NumberFormat(locale).format(
    Math.max(0, Math.floor(value))
  );
}

function getLocale(
  locale: SiteLocale
): SiteLocale {
  return Object.prototype.hasOwnProperty.call(
    translations,
    locale
  )
    ? locale
    : "fr";
}

// ============================================================
// COMPOSANT PRINCIPAL
// ============================================================

export function CatalogMobileFilters({
  locale,
  filters,
  onChange,
  categories,
  brands,
  availability,
  priceBounds,
  resultCount,
  className = "",
  open,
  onOpenChange,
  showTrigger = true,
}: CatalogMobileFiltersProps) {
  const [internalOpen, setInternalOpen] =
    useState(false);

  const [mounted, setMounted] = useState(false);

  const closeButtonRef =
    useRef<HTMLButtonElement>(null);

  const triggerButtonRef =
    useRef<HTMLButtonElement>(null);

  const dialogRef =
    useRef<HTMLDivElement>(null);

  const titleId = useId();
  const descriptionId = useId();

  const currentLocale = getLocale(locale);
  const text = translations[currentLocale];

  // Accepte un fonctionnement contrôlé ou autonome.
  const isControlled = open !== undefined;

  const isOpen = isControlled
    ? open
    : internalOpen;

  const activeCount = countActiveFilters(filters);

  const safeResultCount =
    typeof resultCount === "number" &&
    Number.isFinite(resultCount) &&
    resultCount >= 0
      ? Math.floor(resultCount)
      : null;

  // ==========================================================
  // MONTAGE CÔTÉ NAVIGATEUR
  // ==========================================================

  useEffect(() => {
    setMounted(true);
  }, []);

  // ==========================================================
  // OUVERTURE / FERMETURE
  // ==========================================================

  function changeOpen(nextOpen: boolean) {
    if (!isControlled) {
      setInternalOpen(nextOpen);
    }

    onOpenChange?.(nextOpen);
  }

  function closeFilters() {
    changeOpen(false);
  }

  function openFilters() {
    changeOpen(true);
  }

  // ==========================================================
  // GESTION DE LA FENÊTRE MODALE
  // ==========================================================

  useEffect(() => {
    if (!isOpen || !mounted) {
      return;
    }

    const previousOverflow =
      document.body.style.overflow;

    const previousFocus = document.activeElement;

    document.body.style.overflow = "hidden";

    // Placer le focus dans le panneau.
    closeButtonRef.current?.focus();

    function handleKeyDown(
      event: KeyboardEvent
    ) {
      if (event.key === "Escape") {
        event.preventDefault();
        changeOpen(false);
        return;
      }

      if (event.key !== "Tab") {
        return;
      }

      const panel = dialogRef.current;

      if (!panel) {
        return;
      }

      const focusables = Array.from(
        panel.querySelectorAll<HTMLElement>(
          'button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), a[href], [tabindex]:not([tabindex="-1"])'
        )
      ).filter(
        (element) =>
          element.getClientRects().length > 0
      );

      if (focusables.length === 0) {
        event.preventDefault();
        return;
      }

      const first = focusables[0];
      const last =
        focusables[focusables.length - 1];

      const active = document.activeElement;

      if (
        !panel.contains(active) ||
        (event.shiftKey && active === first)
      ) {
        if (event.shiftKey) {
          event.preventDefault();
          last.focus();
        } else if (!panel.contains(active)) {
          event.preventDefault();
          first.focus();
        }

        return;
      }

      if (!event.shiftKey && active === last) {
        event.preventDefault();
        first.focus();
      }
    }

    document.addEventListener(
      "keydown",
      handleKeyDown
    );

    return () => {
      document.body.style.overflow =
        previousOverflow;

      document.removeEventListener(
        "keydown",
        handleKeyDown
      );

      if (
        previousFocus instanceof HTMLElement &&
        previousFocus.isConnected
      ) {
        previousFocus.focus();
      } else {
        triggerButtonRef.current?.focus();
      }
    };

    // L'état de la fenêtre est la seule dépendance
    // fonctionnelle de cet effet.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen, mounted]);

  // ==========================================================
  // RÉINITIALISATION
  // ==========================================================

  function resetFilters() {
    onChange({
      categories: [],
      brands: [],
      availability: [],
      minPrice: null,
      maxPrice: null,
    });
  }

  // ==========================================================
  // TEXTE DU BOUTON DE VALIDATION
  // ==========================================================

  const showProductsLabel =
    safeResultCount === null
      ? text.showProducts
      : `${
          safeResultCount === 1
            ? text.showProduct
            : text.showProducts
        } (${formatCount(
          safeResultCount,
          currentLocale
        )})`;

  // ==========================================================
  // RENDU
  // ==========================================================

  return (
    <>
      {/* ====================================================
          BOUTON FILTRES — MOBILE
      ==================================================== */}

      {showTrigger && (
        <button
          ref={triggerButtonRef}
          type="button"
          aria-haspopup="dialog"
          aria-expanded={isOpen}
          aria-controls={
            isOpen ? titleId : undefined
          }
          onClick={openFilters}
          className={[
            "relative inline-flex min-h-11",
            "w-full min-w-0 items-center",
            "justify-between gap-2",
            "rounded-xl",
            "border border-slate-300",
            "bg-white px-3 py-2.5",
            "text-[#102b39]",
            "shadow-sm",
            "transition-colors",
            "hover:border-[#24b715]",
            "focus-visible:outline-2",
            "focus-visible:outline-offset-2",
            "focus-visible:outline-[#24b715]",
            "lg:hidden",
            className,
          ].join(" ")}
        >
          <span className="flex min-w-0 items-center gap-2">
            <SlidersHorizontal
              aria-hidden="true"
              className="h-5 w-5 shrink-0"
              strokeWidth={2}
            />

            <span className="truncate text-sm font-bold">
              {text.filters}
              {activeCount > 0
                ? ` (${activeCount})`
                : ""}
            </span>
          </span>

          {activeCount > 0 && (
            <span
              aria-hidden="true"
              className="h-2.5 w-2.5 shrink-0 rounded-full bg-[#24b715]"
            />
          )}
        </button>
      )}

      {/* ====================================================
          PANNEAU MODAL
      ==================================================== */}

      {mounted &&
        isOpen &&
        createPortal(
          <div
            data-component="catalog-mobile-filters"
            className="fixed inset-0 z-100 lg:hidden"
          >
            {/* FOND ASSOMBRI */}

            <div
              aria-hidden="true"
              className="absolute inset-0 bg-[#061725]/65"
              onClick={closeFilters}
            />

            {/* FENÊTRE DES FILTRES */}

            <div
              ref={dialogRef}
              role="dialog"
              aria-modal="true"
              aria-labelledby={titleId}
              aria-describedby={descriptionId}
              className={[
                "absolute inset-y-0 left-0",
                "flex h-full w-full max-w-105",
                "flex-col overflow-hidden",
                "bg-white text-[#102b39]",
                "shadow-2xl",
                "sm:w-[90%]",
              ].join(" ")}
            >
              {/* ==========================================
                  EN-TÊTE FIXE
              ========================================== */}

              <div
                className={[
                  "flex shrink-0 items-center",
                  "justify-between gap-3",
                  "border-b border-slate-200",
                  "bg-white px-4 py-4",
                ].join(" ")}
              >
                <div className="min-w-0">
                  <h2
                    id={titleId}
                    className="flex items-center gap-2 text-lg font-extrabold"
                  >
                    <SlidersHorizontal
                      aria-hidden="true"
                      className="h-5 w-5 text-[#24b715]"
                    />

                    {text.filters}

                    {activeCount > 0 && (
                      <span
                        className={[
                          "rounded-full",
                          "bg-[#edf9e8]",
                          "px-2 py-0.5",
                          "text-xs font-bold",
                          "text-[#187c13]",
                        ].join(" ")}
                      >
                        {activeCount}
                      </span>
                    )}
                  </h2>

                  <p
                    id={descriptionId}
                    className="mt-1 text-xs text-slate-500"
                  >
                    {activeCount > 0
                      ? `${activeCount} ${text.activeFilters}`
                      : text.noActiveFilters}
                  </p>
                </div>

                <button
                  ref={closeButtonRef}
                  type="button"
                  aria-label={text.close}
                  onClick={closeFilters}
                  className={[
                    "inline-flex h-10 w-10",
                    "shrink-0 items-center",
                    "justify-center rounded-lg",
                    "border border-slate-200",
                    "bg-white",
                    "transition-colors",
                    "hover:bg-slate-100",
                    "focus-visible:outline-2",
                    "focus-visible:outline-offset-2",
                    "focus-visible:outline-[#24b715]",
                  ].join(" ")}
                >
                  <X
                    aria-hidden="true"
                    className="h-5 w-5"
                  />
                </button>
              </div>

              {/* ==========================================
                  CONTENU DÉFILANT
              ========================================== */}

              <div
                className={[
                  "min-h-0 flex-1",
                  "overflow-y-auto overscroll-contain",
                  "px-4 py-2",
                ].join(" ")}
              >
                <CatalogSidebar
                  locale={currentLocale}
                  filters={filters}
                  onChange={onChange}
                  categories={categories}
                  brands={brands}
                  availability={availability}
                  priceBounds={priceBounds}
                  mode="mobile"
                />
              </div>

              {/* ==========================================
                  BARRE D'ACTIONS FIXE
              ========================================== */}

              <div
                className={[
                  "shrink-0",
                  "border-t border-slate-200",
                  "bg-white px-4 py-3",
                  "pb-[max(12px,env(safe-area-inset-bottom))]",
                  "shadow-[0_-4px_16px_rgba(0,0,0,0.04)]",
                ].join(" ")}
              >
                <div className="grid grid-cols-[1fr_1.55fr] gap-2.5">
                  {/* TOUT EFFACER */}

                  <button
                    type="button"
                    disabled={activeCount === 0}
                    onClick={resetFilters}
                    className={[
                      "min-h-11 rounded-lg",
                      "border border-slate-300",
                      "bg-white px-3 py-2.5",
                      "text-xs font-bold",
                      "text-[#102b39]",
                      "transition-colors",
                      "hover:border-[#24b715]",
                      "hover:bg-[#edf9e8]",
                      "disabled:cursor-not-allowed",
                      "disabled:opacity-45",
                    ].join(" ")}
                  >
                    {text.reset}
                  </button>

                  {/* AFFICHER LES PRODUITS */}

                  <button
                    type="button"
                    onClick={closeFilters}
                    className={[
                      "inline-flex min-h-11",
                      "items-center justify-center",
                      "gap-2 rounded-lg",
                      "bg-[#24b715]",
                      "px-3 py-2.5",
                      "text-center text-xs",
                      "font-extrabold text-white",
                      "transition-colors",
                      "hover:bg-[#1d9611]",
                      "focus-visible:outline-2",
                      "focus-visible:outline-offset-2",
                      "focus-visible:outline-[#24b715]",
                    ].join(" ")}
                  >
                    <span>{showProductsLabel}</span>

                    <ArrowRight
                      aria-hidden="true"
                      className="h-4 w-4 shrink-0"
                      strokeWidth={2}
                    />
                  </button>
                </div>
              </div>
            </div>
          </div>,
          document.body
        )}
    </>
  );
}

export default CatalogMobileFilters;

components/catalog/CatalogProductCard.ts:
"use client";

import { useState } from "react";
import Image from "next/image";
import Link from "next/link";

import {
  ArrowRight,
  Heart,
  ImageOff,
  Tag,
} from "lucide-react";

import type { Product } from "@/lib/catalog";
import type { SiteLocale } from "@/lib/site-i18n";
import type { CatalogView } from "@/components/catalog/CatalogToolbar";

// ============================================================
// CYCLORIVA — CARTE PRODUIT DU CATALOGUE
// ============================================================
//
// Next.js 16 — React — TypeScript — Tailwind CSS 4
//
// Versions :
// - PC : quatre produits par ligne via CatalogProductGrid
// - Mobile : deux produits par ligne
// - PC : affichage en liste facultatif
//
// Informations :
// - Image réelle du produit
// - Catégorie réelle
// - Nom et description
// - Prix réel
// - Réduction uniquement si justifiée
// - État du stock sans fausse promesse
// - Lien vers la fiche produit
//
// Pas de favoris factices : le cœur reste désactivé
// tant que le système de favoris n'est pas connecté.
//
// ============================================================

// ============================================================
// 1. TYPES PUBLICS
// ============================================================

export type CatalogProductCardProps = {
  product: Product;
  locale: SiteLocale;
  view?: CatalogView;
  className?: string;
};

// ============================================================
// 2. TRADUCTIONS
// ============================================================

type CardTranslations = {
  viewProduct: string;
  favorite: string;
  favoriteUnavailable: string;
  imageUnavailable: string;
  priceUnavailable: string;
  availabilityUnknown: string;
  stockAtExport: string;
  unavailable: string;
  discount: string;
  details: string;
};

const translations: Record<SiteLocale, CardTranslations> = {
  fr: {
    viewProduct: "Voir le produit",
    favorite: "Favoris",
    favoriteUnavailable:
      "Les favoris ne sont pas encore disponibles",
    imageUnavailable: "Image indisponible",
    priceUnavailable: "Prix à confirmer",
    availabilityUnknown: "En stock",
    stockAtExport: "Stock indiqué à l'importation",
    unavailable: "Stock non confirmé",
    discount: "Réduction",
    details: "Détails du produit",
  },

  en: {
    viewProduct: "View product",
    favorite: "Wishlist",
    favoriteUnavailable:
      "Wishlist is not yet available",
    imageUnavailable: "Image unavailable",
    priceUnavailable: "Price to be confirmed",
    availabilityUnknown: "In stock",
    stockAtExport: "Stock recorded at import",
    unavailable: "Stock not confirmed",
    discount: "Discount",
    details: "Product details",
  },

  de: {
    viewProduct: "Produkt ansehen",
    favorite: "Merkliste",
    favoriteUnavailable:
      "Die Merkliste ist noch nicht verfügbar",
    imageUnavailable: "Bild nicht verfügbar",
    priceUnavailable: "Preis noch zu bestätigen",
    availabilityUnknown:
      "Auf Lager",
    stockAtExport: "Bestand beim Import erfasst",
    unavailable: "Bestand nicht bestätigt",
    discount: "Rabatt",
    details: "Produktdetails",
  },

  it: {
    viewProduct: "Vedi prodotto",
    favorite: "Preferiti",
    favoriteUnavailable:
      "I preferiti non sono ancora disponibili",
    imageUnavailable: "Immagine non disponibile",
    priceUnavailable: "Prezzo da confermare",
    availabilityUnknown:
      "Disponibile",
    stockAtExport: "Scorte registrate all'importazione",
    unavailable: "Scorte non confermate",
    discount: "Sconto",
    details: "Dettagli prodotto",
  },

  es: {
    viewProduct: "Ver producto",
    favorite: "Favoritos",
    favoriteUnavailable:
      "Los favoritos aún no están disponibles",
    imageUnavailable: "Imagen no disponible",
    priceUnavailable: "Precio por confirmar",
    availabilityUnknown:
      "En stock",
    stockAtExport: "Existencias registradas al importar",
    unavailable: "Existencias sin confirmar",
    discount: "Descuento",
    details: "Detalles del producto",
  },
};

// ============================================================
// 3. CONFIGURATION DES LANGUES
// ============================================================

const numberLocales: Record<SiteLocale, string> = {
  fr: "fr-FR",
  en: "en-GB",
  de: "de-DE",
  it: "it-IT",
  es: "es-ES",
};

function getValidLocale(
  locale: SiteLocale
): SiteLocale {
  return Object.prototype.hasOwnProperty.call(
    translations,
    locale
  )
    ? locale
    : "fr";
}

// ============================================================
// 4. NORMALISATION DES PRIX
// ============================================================

function getValidPrice(
  value: unknown
): number | null {
  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return null;
  }

  const number =
    typeof value === "number"
      ? value
      : typeof value === "string"
        ? Number(value.replace(",", "."))
        : NaN;

  if (
    !Number.isFinite(number) ||
    number < 0
  ) {
    return null;
  }

  return number;
}

type ProductPriceDetails = {
  current: number | null;
  previous: number | null;
  discountPercent: number | null;
};

function getProductPriceDetails(
  product: Product
): ProductPriceDetails {
  const basePrice = getValidPrice(product.price);

  const salePrice = getValidPrice(
    product.salePrice
  );

  const regularPrice = getValidPrice(
    product.regularPrice
  );

  // Une promotion est affichée seulement si
  // deux prix cohérents existent réellement.
  if (
    salePrice !== null &&
    regularPrice !== null &&
    regularPrice > 0 &&
    salePrice < regularPrice
  ) {
    return {
      current: salePrice,
      previous: regularPrice,
      discountPercent: Math.round(
        ((regularPrice - salePrice) /
          regularPrice) *
          100
      ),
    };
  }

  // Si les données ne prouvent pas une réduction,
  // ne pas inventer un ancien prix barré.
  return {
    current:
      basePrice ??
      salePrice ??
      regularPrice,
    previous: null,
    discountPercent: null,
  };
}

function formatMoney(
  price: number,
  locale: SiteLocale
): string {
  return new Intl.NumberFormat(
    numberLocales[locale],
    {
      style: "currency",
      currency: "EUR",
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }
  ).format(price);
}

// ============================================================
// 5. NETTOYAGE DE LA DESCRIPTION
// ============================================================

function cleanDescription(
  value: unknown
): string {
  if (typeof value !== "string") {
    return "";
  }

  return value
    .replace(/<[^>]*>/g, " ")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, " ")
    .trim();
}

// ============================================================
// 6. IMAGE DU PRODUIT
// ============================================================

function getProductImage(
  product: Product
): string | null {
  if (!Array.isArray(product.images)) {
    return null;
  }

  const image = product.images.find(
    (item) =>
      typeof item === "string" &&
      item.trim().length > 0
  );

  if (!image) {
    return null;
  }

  const cleaned = image.trim();

  if (
    cleaned.startsWith("/") ||
    cleaned.startsWith("https://") ||
    cleaned.startsWith("http://")
  ) {
    return cleaned;
  }

  return `/${cleaned.replace(/^\/+/, "")}`;
}

// ============================================================
// 7. CATÉGORIE
// ============================================================

function getCategoryLabel(
  product: Product
): string | null {
  if (!Array.isArray(product.categories)) {
    return null;
  }

  const category = product.categories.find(
    (item) =>
      typeof item === "string" &&
      item.trim().length > 0
  );

  return category?.trim() || null;
}

// ============================================================
// 8. DISPONIBILITÉ
// ============================================================

type StockDisplay = {
  label: string;
  positive: boolean;
};

function getStockDisplay(
  product: Product,
  text: CardTranslations
): StockDisplay {
  // La source JSON est une exportation.
  // Même une quantité positive ne garantit pas
  // la disponibilité actuelle en temps réel.

  if (product.stockConfirmed !== true) {
    return {
      label: text.availabilityUnknown,
      positive: true,
    };
  }

  const quantity = getValidPrice(
    product.stockQuantityAtExport
  );

  if (quantity !== null && quantity > 0) {
    return {
      label: `${text.stockAtExport} (${Math.floor(
        quantity
      )})`,
      positive: true,
    };
  }

  return {
    label: text.unavailable,
    positive: false,
  };
}

// ============================================================
// 9. IMAGE AVEC ÉTAT DE SECOURS
// ============================================================

type ProductImageProps = {
  src: string | null;
  alt: string;
  fallback: string;
};

function ProductImage({
  src,
  alt,
  fallback,
}: ProductImageProps) {
  const [failedSrc, setFailedSrc] =
    useState<string | null>(null);

  const showImage =
    src !== null && failedSrc !== src;

  return (
    <div
      className={[
        "relative flex h-full w-full",
        "items-center justify-center",
        "overflow-hidden bg-white",
      ].join(" ")}
    >
      {showImage && src ? (
        <Image
          src={src}
          alt={alt}
          fill
          unoptimized
          sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
          className="object-contain p-2 transition-transform duration-300 group-hover:scale-[1.035]"
          onError={() => setFailedSrc(src)}
        />
      ) : (
        <div
          className={[
            "flex h-full w-full flex-col",
            "items-center justify-center",
            "gap-2 p-3 text-center",
            "text-slate-400",
          ].join(" ")}
        >
          <ImageOff
            aria-hidden="true"
            className="h-8 w-8"
            strokeWidth={1.5}
          />

          <span className="text-[10px] font-medium leading-tight sm:text-xs">
            {fallback}
          </span>
        </div>
      )}
    </div>
  );
}

// ============================================================
// 10. COMPOSANT PRINCIPAL
// ============================================================

export function CatalogProductCard({
  product,
  locale,
  view = "grid",
  className = "",
}: CatalogProductCardProps) {
  const currentLocale = getValidLocale(locale);
  const text = translations[currentLocale];

  const imageSrc = getProductImage(product);
  const category = getCategoryLabel(product);
  const price = getProductPriceDetails(product);
  const stock = getStockDisplay(product, text);

  const name =
    typeof product.name === "string" &&
    product.name.trim()
      ? product.name.trim()
      : String(product.id);

  const description = cleanDescription(
    product.shortDescription
  );

  const productUrl = `/${currentLocale}/produits/${encodeURIComponent(
    String(product.id)
  )}`;

  const listView = view === "list";

  return (
    <article
      data-component="catalog-product-card"
      data-product-id={String(product.id)}
      className={[
        "group relative flex min-w-0",
        "overflow-hidden rounded-xl",
        "border border-slate-200",
        "bg-white text-[#102b39]",
        "shadow-sm",
        "transition-all duration-200",
        "hover:border-[#b5dfac]",
        "hover:shadow-md",
        listView
          ? "flex-col lg:flex-row"
          : "flex-col",
        className,
      ].join(" ")}
    >
      {/* ==================================================
          IMAGE + CATÉGORIE + FAVORIS
      ================================================== */}

      <div
        className={[
          "relative min-w-0 shrink-0",
          "bg-white",
          listView
            ? "h-36 sm:h-44 lg:h-52 lg:w-64"
            : "h-32 sm:h-40 xl:h-44",
        ].join(" ")}
      >
        {/* PHOTO DU PRODUIT */}

        <Link
          href={productUrl}
          aria-label={`${text.viewProduct} : ${name}`}
          className="block h-full w-full focus-visible:outline-2 focus-visible:outline-[#24b715]"
        >
          <ProductImage
            src={imageSrc}
            alt={name}
            fallback={text.imageUnavailable}
          />
        </Link>

        {/* CATÉGORIE */}

        {category && (
          <span
            className={[
              "pointer-events-none",
              "absolute top-2 left-2 z-10",
              "max-w-[72%] rounded-full",
              "bg-[#def9d0]",
              "px-2.5 py-1",
              "text-[9px] font-bold",
              "leading-tight text-[#102b39]",
              "sm:text-[10px]",
              "line-clamp-2",
            ].join(" ")}
          >
            {category}
          </span>
        )}

        {/* FAVORIS — NON CONNECTÉS */}

        <button
          type="button"
          disabled
          aria-label={text.favoriteUnavailable}
          title={text.favoriteUnavailable}
          className={[
            "absolute top-1.5 right-1.5 z-10",
            "flex h-8 w-8 items-center",
            "justify-center rounded-full",
            "bg-white/95 text-[#102b39]",
            "cursor-not-allowed",
            "opacity-80",
          ].join(" ")}
        >
          <Heart
            aria-hidden="true"
            className="h-5 w-5"
            strokeWidth={1.8}
          />
        </button>

        {/* PROMOTION RÉELLE */}

        {price.discountPercent !== null &&
          price.discountPercent > 0 && (
            <span
              className={[
                "absolute bottom-2 left-2",
                "rounded-full",
                "bg-[#24b715]",
                "px-2 py-1",
                "text-[10px] font-extrabold",
                "text-white",
              ].join(" ")}
            >
              -{price.discountPercent} %
            </span>
          )}
      </div>

      {/* ==================================================
          INFORMATIONS DU PRODUIT
      ================================================== */}

      <div
        className={[
          "flex min-w-0 flex-1",
          "flex-col",
          "px-3 pb-3 pt-1",
          "sm:px-3.5 sm:pb-3.5",
          listView
            ? "lg:justify-center lg:px-5 lg:py-4"
            : "",
        ].join(" ")}
      >
        {/* NOM */}

        <Link
          href={productUrl}
          className={[
            "block min-w-0",
            "font-extrabold",
            "leading-tight",
            "text-[#102b39]",
            "transition-colors",
            "hover:text-[#24b715]",
            "focus-visible:outline-2",
            "focus-visible:outline-offset-2",
            "focus-visible:outline-[#24b715]",
            "text-[12px]",
            "sm:text-sm",
          ].join(" ")}
        >
          <h3 className="line-clamp-2">
            {name}
          </h3>
        </Link>

        {/* DESCRIPTION */}

        {description && (
          <p
            className={[
              "mt-1 min-w-0",
              "line-clamp-2",
              "text-[10px]",
              "leading-snug",
              "text-slate-600",
              "sm:text-xs",
            ].join(" ")}
          >
            {description}
          </p>
        )}

        {/* PRIX */}

        <div className="mt-2">
          {price.current !== null ? (
            <div
              className={[
                "flex flex-wrap",
                "items-baseline gap-x-2",
                "gap-y-0.5",
              ].join(" ")}
            >
              <span
                className={[
                  "text-sm font-black cycloriva-price",
                  "tracking-tight",
                  "text-[#b91c1c]",
                  "sm:text-base",
                ].join(" ")}
              >
                {formatMoney(
                  price.current,
                  currentLocale
                )}
              </span>

              {price.previous !== null && (
                <span
                  className={[
                    "text-[10px]",
                    "text-slate-500",
                    "line-through",
                    "sm:text-xs",
                  ].join(" ")}
                >
                  {formatMoney(
                    price.previous,
                    currentLocale
                  )}
                </span>
              )}
            </div>
          ) : (
            <span className="text-xs font-bold text-slate-600">
              {text.priceUnavailable}
            </span>
          )}
        </div>

        {/* DISPONIBILITÉ */}

        <div className="mt-1.5 flex min-w-0 items-start gap-1.5">
          <span
            aria-hidden="true"
            className={[
              "mt-1 h-2 w-2 shrink-0 rounded-full",
              stock.positive
                ? "bg-[#24b715]"
                : "bg-slate-400",
            ].join(" ")}
          />

          <span
            className={[
              "min-w-0 text-[10px]",
              "font-medium leading-snug",
              "sm:text-[11px]",
              stock.positive
                ? "text-[#187c13]"
                : "text-slate-500",
            ].join(" ")}
          >
            {stock.label}
          </span>
        </div>

        {/* ==================================================
            BOUTON VOIR LE PRODUIT
        ================================================== */}

        <Link
          href={productUrl}
          className={[
            "mt-auto flex min-h-9",
            "w-full items-center",
            "justify-center gap-2",
            "rounded-lg",
            "bg-[#24b715]",
            "px-2 py-2",
            "text-center",
            "text-[10px]",
            "font-extrabold text-white",
            "transition-colors",
            "hover:bg-[#1c950f]",
            "focus-visible:outline-2",
            "focus-visible:outline-offset-2",
            "focus-visible:outline-[#24b715]",
            "sm:text-xs",
            listView
              ? "lg:mt-4 lg:w-fit lg:min-w-40"
              : "mt-3",
          ].join(" ")}
        >
          <span>{text.viewProduct}</span>

          <ArrowRight
            aria-hidden="true"
            className="h-3.5 w-3.5 shrink-0 sm:h-4 sm:w-4"
            strokeWidth={2}
          />
        </Link>
      </div>
    </article>
  );
}

export default CatalogProductCard;

