import Link from "next/link";
import "./HomeHero.css";

import {
  ArrowRight,
  Zap,
  ShieldCheck,
  Leaf,
} from "lucide-react";

import {
  getHomeTranslations,
} from "@/lib/home-i18n";

import {
  resolveLocale,
  type SiteLocale,
} from "@/lib/site-i18n";

// =====================================================
// CYCLORIVA — COUVERTURE OFFICIELLE DE L'ACCUEIL
// =====================================================
//
// Next.js 16 • TypeScript • Tailwind CSS 4
//
// Image : /images/couverture.png
//
// PC :
// - Grand bandeau horizontal
// - Textes et boutons à gauche
// - Vélo visible sur la droite
// - Trois avantages sur la droite
//
// Mobile :
// - Titre sur plusieurs lignes
// - Image adaptée à la largeur
// - Boutons superposés
// - Avantages compacts sur la droite
//
// Traductions : FR, EN, DE, IT, ES
//
// =====================================================

// =====================================================
// TYPES
// =====================================================

type HomeHeroProps = {
  locale: SiteLocale;
  className?: string;
};

// =====================================================
// COMPOSANT PRINCIPAL
// =====================================================

export function HomeHero({
  locale,
  className = "",
}: HomeHeroProps) {
  const currentLocale = resolveLocale(locale);

  const text = getHomeTranslations(currentLocale).hero;

  const electricBikesUrl =
    `/${currentLocale}/produits?q=${encodeURIComponent(
      "électrique"
    )}`;

  const categoriesUrl = "#categories";

  const benefits = [
    {
      key: "performance",
      label: text.performance,
      icon: Zap,
    },
    {
      key: "reliable",
      label: text.reliable,
      icon: ShieldCheck,
    },
    {
      key: "durable",
      label: text.durable,
      icon: Leaf,
    },
