      `}
    >
      {/* =================================================
          IMAGE DE COUVERTURE OFFICIELLE
      ================================================= */}

      <div
        aria-hidden="true"
        className="absolute inset-0 z-0"
      >
        <img
          src="/images/couverture.png"
          alt=""
          width={1920}
          height={720}
          fetchPriority="high"
          decoding="async"
          className="
            h-full w-full
            object-cover
            object-[60%_center]
            sm:object-center
          "
        />
      </div>

      {/* =================================================
          VOILE POUR LA LISIBILITÉ DU TEXTE
      ================================================= */}

      <div
        aria-hidden="true"
        className="
          absolute inset-0 z-0
          bg-linear-to-r
          from-[#061b2d]/95
          via-[#102b39]/80
          to-[#102b39]/10
          sm:from-[#061b2d]/90
          sm:via-[#102b39]/45
          sm:to-transparent
          lg:from-[#061b2d]/75
          lg:via-[#102b39]/25
        "
      />

      {/* =================================================
          CONTENU PRINCIPAL
      ================================================= */}

      <div
        className={`
          cycloriva-container
          relative z-10
          flex min-h-112 flex-col
          justify-center
          py-7
          sm:min-h-110
          sm:py-10
          lg:min-h-88
          lg:py-10
          xl:min-h-100
          cycloriva-hero-content
        `}
      >
        <div
          className={`
            grid grid-cols-1
            gap-5
            lg:grid-cols-[minmax(0,1fr)_220px]
