                {text.eyebrow}
              </p>
            </div>

            {/* GRAND TITRE */}
            <h1
              id="home-hero-title"
              className={`
                max-w-145
                text-[30px] font-black
                leading-[1.08]
                tracking-tight
                text-white
                sm:text-4xl
                lg:text-[43px]
                xl:text-[48px]
                cycloriva-hero-title
              `}
            >
              <span className="block">
                {text.titleLine1}
              </span>

              <span className="block">
                {text.titleLine2}{" "}
                <span className={`text-[#8ce900] cycloriva-hero-highlight`}>
                  {text.titleHighlight}
