components/home/HomeProductCard.tsx:
"use client";

import Link from "next/link";
import { useState } from "react";

import {
  ArrowRight,
  Heart,
  ImageOff,
  ShoppingCart,
} from "lucide-react";

import {
  currentPrice,
  formatPrice,
  localizedProduct,
  stripHtml,
  type Product,
} from "@/lib/catalog";

import {
  resolveLocale,
  type SiteLocale,
} from "@/lib/site-i18n";

// =====================================================
// CYCLORIVA — CARTE PRODUIT OFFICIELLE
// =====================================================
//
// Compatible : Next.js 16, React, TypeScript
//
// Responsive :
// - Mobile : 2 produits par ligne
// - Tablette : 2 produits par ligne
// - PC : 4 produits par ligne
//
// Fonctionnalités :
// - Image originale du catalogue
// - Nom et description du produit
// - Prix réel en euros
// - Ancien prix si promotion vérifiable
// - Badge de réduction si applicable
// - Favoris visuels
// - Lien vers la fiche produit
// - Gestion des images indisponibles
// - Traductions FR, EN, DE, IT, ES
//
// =====================================================

// =====================================================
// TYPES
// =====================================================

export type HomeProductCardProps = {
  product: Product;
  locale: SiteLocale;
  className?: string;
  compact?: boolean;
};

// =====================================================
// TRADUCTIONS DE LA CARTE PRODUIT
// =====================================================

const translations = {
  fr: {
    view: "Voir le produit",
    imageMissing: "Image indisponible",
    priceMissing: "Prix à confirmer",
    favorite: "Favoris bientôt disponibles",
    translation: "Traduction en préparation",
    stock: "En stock",
    promotion: "Réduction",
  },

  en: {
    view: "View product",
    imageMissing: "Image unavailable",
    priceMissing: "Price to be confirmed",
    favorite: "Wishlist coming soon",
    translation: "Translation in progress",
    stock: "In stock",
    promotion: "Discount",
  },

  de: {
    view: "Produkt ansehen",
    imageMissing: "Bild nicht verfügbar",
    priceMissing: "Preis noch zu bestätigen",
    favorite: "Merkliste bald verfügbar",
    translation: "Übersetzung in Vorbereitung",
    stock: "Auf Lager",
    promotion: "Rabatt",
  },

  it: {
    view: "Vedi prodotto",
    imageMissing: "Immagine non disponibile",
    priceMissing: "Prezzo da confermare",
    favorite: "Preferiti disponibili prossimamente",
    translation: "Traduzione in preparazione",
    stock: "Disponibile",
    promotion: "Sconto",
  },

  es: {
    view: "Ver producto",
    imageMissing: "Imagen no disponible",
    priceMissing: "Precio por confirmar",
    favorite: "Favoritos próximamente",
    translation: "Traducción en preparación",
    stock: "En stock",
    promotion: "Descuento",
  },
} as const;

// =====================================================
// VÉRIFICATION DE LA PROMOTION
// =====================================================

function getDiscount(product: Product): number | null {
  const regularPrice = product.regularPrice;
  const salePrice = product.salePrice;

  if (
    regularPrice === null ||
    salePrice === null ||
    !Number.isFinite(regularPrice) ||
    !Number.isFinite(salePrice) ||
    regularPrice <= 0 ||
    salePrice < 0 ||
    salePrice >= regularPrice
  ) {
    return null;
  }

  return Math.round(
    ((regularPrice - salePrice) / regularPrice) * 100
  );
}

// =====================================================
// DESCRIPTION COURTE
// =====================================================

function getDescription(
  product: Product,
  locale: SiteLocale
): string {
  const localized = localizedProduct(product, locale);

  const description = stripHtml(
    localized.shortDescription ||
      localized.description ||
      ""
  );

  if (description.length <= 115) {
    return description;
  }

  return `${description.slice(0, 112).trimEnd()}…`;
}

// =====================================================
// COMPOSANT PRINCIPAL
// =====================================================

export function HomeProductCard({
  product,
  locale,
  className = "",
  compact = false,
}: HomeProductCardProps) {
  const currentLocale = resolveLocale(locale);
  const tr = translations[currentLocale];

  const [imageError, setImageError] = useState(false);

  const localized = localizedProduct(
    product,
    currentLocale
  );

  const price = currentPrice(product);
  const discount = getDiscount(product);

  const description = getDescription(
    product,
    currentLocale
  );

  const image =
    product.images.find(
      (value) =>
        typeof value === "string" &&
        value.trim().length > 0
    ) ?? null;

  const imageAvailable = Boolean(image && !imageError);

  const productUrl = `/${currentLocale}/produits/${encodeURIComponent(
    product.id
  )}`;

  const showOriginalPrice =
    discount !== null &&
    product.regularPrice !== null;

  return (
    <article
      className={`
        group relative flex h-full min-w-0 flex-col
        overflow-hidden rounded-xl
        border border-slate-200 bg-white
        transition-all duration-200
        hover:border-[#24b715]
        hover:shadow-md
        ${className}
      `}
    >
      {/* =================================================
          IMAGE ET BADGES
      ================================================= */}

      <div className="relative bg-white">
        {/* BADGE PROMOTION */}
        {discount !== null && (
          <span
            className="
              absolute left-2 top-2 z-10
              rounded-full bg-[#24b715]
              px-2.5 py-1
              text-[10px] font-bold text-white
              sm:left-3 sm:top-3
            "
            aria-label={`${tr.promotion} ${discount}%`}
          >
            -{discount}%
          </span>
        )}

        {/* FAVORIS — EN ATTENTE DU MODULE */}
        <button
          type="button"
          disabled
          title={tr.favorite}
          aria-label={tr.favorite}
          className="
            absolute right-2 top-2 z-10
            flex h-8 w-8 items-center
            justify-center rounded-full
            bg-white/90 text-[#102b39]
            opacity-75
            sm:right-3 sm:top-3
          "
        >
          <Heart
            size={19}
            strokeWidth={1.8}
            aria-hidden="true"
          />
        </button>

        {/* IMAGE ORIGINALE */}
        <Link
          href={productUrl}
          aria-label={`${tr.view}: ${localized.name}`}
          className={`
            flex w-full items-center justify-center
            overflow-hidden bg-white
            ${compact
              ? "h-28 sm:h-36"
              : "h-36 sm:h-44 lg:h-48"}
          `}
        >
          {imageAvailable ? (
            <img
              key={image}
              src={image!}
              alt={localized.name}
              loading="lazy"
              decoding="async"
              onError={() => setImageError(true)}
              className="
                h-full w-full object-contain
                p-3 transition-transform
                duration-300
                group-hover:scale-105
              "
            />
          ) : (
            <div
              className="
                flex h-full w-full flex-col
                items-center justify-center
                gap-2 bg-slate-50 p-4
                text-slate-400
              "
            >
              <ImageOff
                size={30}
                strokeWidth={1.5}
                aria-hidden="true"
              />

              <span className="text-center text-[11px]">
                {tr.imageMissing}
              </span>
            </div>
          )}
        </Link>
      </div>

      {/* =================================================
          INFORMATIONS PRODUIT
      ================================================= */}

      <div
        className={`
          flex min-w-0 flex-1 flex-col
          ${compact
            ? "px-2.5 pb-3 pt-2"
            : "px-3 pb-4 pt-2 sm:px-4"}
        `}
      >
        {/* NOM DU PRODUIT */}
        <Link
          href={productUrl}
          className="block"
        >
          <h3
            className="
              line-clamp-2 min-h-10
              text-xs font-extrabold
              leading-5 text-[#102b39]
              transition-colors
              group-hover:text-[#168e0a]
              sm:min-h-12 sm:text-sm
            "
          >
            {localized.name}
          </h3>
        </Link>

        {/* DESCRIPTION COURTE */}
        {description && (
          <p
            className="
              mt-1 line-clamp-2
              text-[10px] leading-4
              text-slate-500 sm:text-xs
            "
          >
            {description}
          </p>
        )}

        {/* ESPACE FLEXIBLE */}
        <div className="flex-1" />

        {/* =================================================
            PRIX ET BOUTON
        ================================================= */}

        <div
          className="
            mt-3 flex items-end
            justify-between gap-2
          "
        >
          <div className="min-w-0">
            {/* PRIX ACTUEL */}
            <p
              className="
                text-sm font-extrabold cycloriva-price
                text-[#b91c1c]
                sm:text-lg
              "
            >
              {price !== null
                ? formatPrice(price, currentLocale)
                : tr.priceMissing}
            </p>

            {/* ANCIEN PRIX */}
            {showOriginalPrice && (
              <p
                className="
                  mt-0.5 text-[10px]
                  text-slate-400 line-through
                  sm:text-xs
                "
              >
                {formatPrice(
                  product.regularPrice,
                  currentLocale
                )}
              </p>
            )}
          </div>

          {/* BOUTON VERT VERS LA FICHE PRODUIT */}
          <Link
            href={productUrl}
            title={tr.view}
            aria-label={`${tr.view}: ${localized.name}`}
            className="
              flex h-8 w-8 shrink-0
              items-center justify-center
              rounded-lg bg-[#24b715]
              text-white
              transition-colors
              hover:bg-[#168e0a]
              focus-visible:outline-2
              focus-visible:outline-offset-2
              focus-visible:outline-[#24b715]
              sm:h-9 sm:w-9
            "
          >
            {compact ? (
              <ArrowRight
                size={17}
                strokeWidth={2.2}
                aria-hidden="true"
              />
            ) : (
              <ShoppingCart
                size={17}
                strokeWidth={2}
                aria-hidden="true"
              />
            )}
          </Link>
        </div>

        {/* =================================================
            INFORMATIONS COMPLÉMENTAIRES
        ================================================= */}

        {!localized.translated && (
          <p
            className="
              mt-2 text-[10px]
              leading-4 text-slate-500
            "
          >
            {tr.translation}
          </p>
        )}

        {!product.stockConfirmed && (
          <p
            className="
              mt-1 text-[10px]
              leading-4 text-amber-700
            "
          >
            {tr.stock}
          </p>
        )}
      </div>
    </article>
  );
}

export default HomeProductCard;

components/home/HomeProducts.tsx:
import Link from "next/link";

import {
  ArrowRight,
  ShoppingCart,
  ImageOff,
} from "lucide-react";

import {
  allProducts,
  currentPrice,
  formatPrice,
  localizedProduct,
  stripHtml,
  type Product,
} from "@/lib/catalog";

import {
  resolveLocale,
  type SiteLocale,
} from "@/lib/site-i18n";

// =====================================================
// CYCLORIVA — PRODUITS DE LA PAGE D'ACCUEIL
// =====================================================
//
// Responsive :
// - Mobile : 2 produits par ligne
// - Tablette : 2 produits par ligne
// - PC : 4 produits par ligne
//
// Données : data/products.json via lib/catalog.ts
//
// Les données commerciales ne sont pas inventées.
// Les produits sont affichés depuis le catalogue.
//
// Aucun panier fonctionnel n'est simulé.
//
// =====================================================

// =====================================================
// TYPES
// =====================================================

type HomeProductsVariant =
  | "featured"
  | "new";

type HomeProductsProps = {
  locale: SiteLocale;
  variant?: HomeProductsVariant;
  limit?: number;
  products?: Product[];
  className?: string;
};

// =====================================================
// TRADUCTIONS
// =====================================================

const translations = {
  fr: {
    featured: "Produits phares",
    new: "Nouveautés",
    viewAll: "Voir tous les produits",
    viewNew: "Voir tous les produits",
    viewProduct: "Voir le produit",
    priceMissing: "Prix à confirmer",
    imageMissing: "Image indisponible",
    stock: "En stock",
    translation: "Traduction en préparation",
    empty: "Aucun produit à afficher pour le moment.",
    promotion: "Promotion",
  },

  en: {
    featured: "Featured products",
    new: "New arrivals",
    viewAll: "View all products",
    viewNew: "View all products",
    viewProduct: "View product",
    priceMissing: "Price to be confirmed",
    imageMissing: "Image unavailable",
    stock: "In stock",
    translation: "Translation in progress",
    empty: "No products to display at the moment.",
    promotion: "Sale",
  },

  de: {
    featured: "Ausgewählte Produkte",
    new: "Neuheiten",
    viewAll: "Alle Produkte ansehen",
    viewNew: "Alle Produkte ansehen",
    viewProduct: "Produkt ansehen",
    priceMissing: "Preis auf Anfrage",
    imageMissing: "Bild nicht verfügbar",
    stock: "Auf Lager",
    translation: "Übersetzung in Vorbereitung",
    empty: "Derzeit keine Produkte verfügbar.",
    promotion: "Angebot",
  },

  it: {
    featured: "Prodotti in evidenza",
    new: "Novità",
    viewAll: "Vedi tutti i prodotti",
    viewNew: "Vedi tutti i prodotti",
    viewProduct: "Vedi prodotto",
    priceMissing: "Prezzo da confermare",
    imageMissing: "Immagine non disponibile",
    stock: "Disponibile",
    translation: "Traduzione in preparazione",
    empty: "Nessun prodotto da visualizzare.",
    promotion: "Offerta",
  },

  es: {
    featured: "Productos destacados",
    new: "Novedades",
    viewAll: "Ver todos los productos",
    viewNew: "Ver todos los productos",
    viewProduct: "Ver producto",
    priceMissing: "Precio por confirmar",
    imageMissing: "Imagen no disponible",
    stock: "En stock",
    translation: "Traducción en preparación",
    empty: "No hay productos para mostrar.",
    promotion: "Oferta",
  },
} as const;

// =====================================================
// SÉLECTION DES PRODUITS
// =====================================================

/**
 * Sélectionne uniquement de vrais produits
 * présents dans le catalogue.
 *
 * La section "featured" utilise les premiers
 * produits exploitables.
 *
 * La section "new" utilise des produits différents,
 * mais leur ancienneté n'est pas garantie :
 * le JSON ne fournit pas de date fiable.
 */

function selectHomeProducts(
  variant: HomeProductsVariant,
  limit: number
): Product[] {
  const eligibleProducts = allProducts.filter(
    (product) =>
      product.id.length > 0 &&
      product.name.trim().length > 0 &&
      product.images.length > 0
  );

  if (variant === "featured") {
    return eligibleProducts.slice(0, limit);
  }

  return eligibleProducts.slice(
    limit,
    limit * 2
  );
}

// =====================================================
// VÉRIFICATION DU PRIX PROMOTIONNEL
// =====================================================

function getPromotion(
  product: Product
): number | null {
  const regular = product.regularPrice;
  const sale = product.salePrice;

  if (
    regular === null ||
    sale === null ||
    !Number.isFinite(regular) ||
    !Number.isFinite(sale) ||
    regular <= 0 ||
    sale < 0 ||
    sale >= regular
  ) {
    return null;
  }

  const percentage =
    ((regular - sale) / regular) * 100;

  return Math.round(percentage);
}

// =====================================================
// DESCRIPTION COURTE
// =====================================================

function getShortDescription(
  product: Product,
  locale: SiteLocale
): string {
  const localized = localizedProduct(
    product,
    locale
  );

  const raw =
    localized.shortDescription ||
    localized.description ||
    "";

  const text = stripHtml(raw);

  return text.length > 110
    ? `${text.slice(0, 107).trimEnd()}…`
    : text;
}

// =====================================================
// CARTE D'UN PRODUIT
// =====================================================

function ProductCard({
  product,
  locale,
}: {
  product: Product;
  locale: SiteLocale;
}) {
  const tr = translations[locale];

  const localized = localizedProduct(
    product,
    locale
  );

  const price = currentPrice(product);

  const promotion = getPromotion(product);

  const image =
    product.images.find(
      (value) =>
        typeof value === "string" &&
        value.trim().length > 0
    ) ?? null;

  const description = getShortDescription(
    product,
    locale
  );

  const href = `/${locale}/produits/${encodeURIComponent(
    product.id
  )}`;

  return (
    <article
      className="
        group relative flex h-full min-w-0 flex-col
        overflow-hidden rounded-xl
        border border-slate-200
        bg-white
        transition-colors duration-200
        hover:border-[#24b715]
        hover:shadow-md
      "
    >
      {/* IMAGE ET BADGE */}
      <div className="relative bg-white px-2 pt-3 sm:px-3">
        {/* PROMOTION UNIQUEMENT SI PRÉSENTE */}
        {promotion !== null && (
          <span
            className="
              absolute left-2 top-2 z-10
              rounded-full bg-[#24b715]
              px-2.5 py-1
              text-[10px] font-bold
              text-white sm:left-3
            "
          >
            -{promotion} %
          </span>
        )}

        {/* IMAGE PRINCIPALE */}
        <Link
          href={href}
          aria-label={`${tr.viewProduct} : ${localized.name}`}
          className="
            flex h-32 w-full items-center
            justify-center overflow-hidden
            sm:h-44 lg:h-48
          "
        >
          {image ? (
            <img
              src={image}
              alt={localized.name}
              loading="lazy"
              decoding="async"
              className="
                h-full w-full object-contain
                transition-transform duration-300
                group-hover:scale-105
              "
            />
          ) : (
            <div
              className="
                flex h-full w-full flex-col
                items-center justify-center
                gap-2 text-slate-400
              "
            >
              <ImageOff
                size={30}
                strokeWidth={1.5}
                aria-hidden="true"
              />

              <span className="text-center text-xs">
                {tr.imageMissing}
              </span>
            </div>
          )}
        </Link>
      </div>

      {/* INFORMATIONS */}
      <div className="flex flex-1 flex-col px-3 pb-3 pt-2 sm:px-4 sm:pb-4">
        {/* CATÉGORIE */}
        {product.categories.length > 0 && (
          <p
            className="
              mb-1 truncate text-[10px]
              text-slate-500 sm:text-xs
            "
          >
            {product.categories[0]}
          </p>
        )}

        {/* NOM DU PRODUIT */}
        <Link href={href}>
          <h3
            className="
              line-clamp-2 min-h-10
              text-xs font-extrabold leading-5
              text-[#102b39]
              transition-colors
              group-hover:text-[#168e0a]
              sm:min-h-12 sm:text-sm
            "
          >
            {localized.name}
          </h3>
        </Link>

        {/* DESCRIPTION */}
        {description && (
          <p
            className="
              mt-1 line-clamp-2
              text-[10px] leading-4
              text-slate-500 sm:text-xs
            "
          >
            {description}
          </p>
        )}

        {/* PRIX */}
        <div
          className="
            mt-auto flex items-end
            justify-between gap-2 pt-3
          "
        >
          <div className="min-w-0">
            <p
              className="
                text-sm font-extrabold cycloriva-price
                text-[#b91c1c]
                sm:text-lg
              "
            >
              {price !== null
                ? formatPrice(price, locale)
                : tr.priceMissing}
            </p>

            {/* ANCIEN PRIX UNIQUEMENT EN PROMOTION */}
            {promotion !== null &&
              product.regularPrice !== null && (
                <p
                  className="
                    text-[10px] text-slate-400
                    line-through sm:text-xs
                  "
                >
                  {formatPrice(
                    product.regularPrice,
                    locale
                  )}
                </p>
              )}
          </div>

          {/* LIEN VERS LA FICHE PRODUIT */}
          <Link
            href={href}
            aria-label={`${tr.viewProduct} : ${localized.name}`}
            title={tr.viewProduct}
            className="
              flex h-8 w-8 shrink-0
              items-center justify-center
              rounded-lg bg-[#24b715]
              text-white
              transition-colors
              hover:bg-[#168e0a]
              sm:h-9 sm:w-9
            "
          >
            <ArrowRight
              size={17}
              strokeWidth={2.2}
              aria-hidden="true"
            />
          </Link>
        </div>

        {/* TRADUCTION INCOMPLÈTE */}
        {!localized.translated && (
          <p
            className="
              mt-2 text-[10px]
              leading-4 text-slate-500
            "
          >
            {tr.translation}
          </p>
        )}

        {/* DISPONIBILITÉ NON CONFIRMÉE */}
        {!product.stockConfirmed && (
          <p className="mt-1 text-[10px] text-amber-700">
            {tr.stock}
          </p>
        )}
      </div>
    </article>
  );
}

// =====================================================
// COMPOSANT PRINCIPAL
// =====================================================

export function HomeProducts({
  locale,
  variant = "featured",
  limit = 4,
  products,
  className = "",
}: HomeProductsProps) {
  const currentLocale = resolveLocale(locale);

  const tr = translations[currentLocale];

  const safeLimit = Math.max(
    0,
    Math.floor(
      Number.isFinite(limit) ? limit : 4
    )
  );

  const selectedProducts = products
    ? products.slice(0, safeLimit)
    : selectHomeProducts(variant, safeLimit);

  const title =
    variant === "featured"
      ? tr.featured
      : tr.new;

  const viewAllLabel =
    variant === "featured"
      ? tr.viewAll
      : tr.viewNew;

  const sectionId =
    variant === "featured"
      ? "home-featured-products"
      : "home-new-products";

  return (
    <section
      id={sectionId}
      aria-labelledby={`${sectionId}-title`}
      className={`w-full bg-white py-5 sm:py-7 ${className}`}
    >
      <div className="cycloriva-container">
        {/* EN-TÊTE DE SECTION */}
        <div
          className="
            mb-4 flex flex-wrap
            items-end justify-between
            gap-2 sm:mb-5
          "
        >
          <div>
            <h2
              id={`${sectionId}-title`}
              className="
                text-xl font-extrabold
                tracking-tight text-[#102b39]
                sm:text-2xl
              "
            >
              {title}
            </h2>

            <div
              aria-hidden="true"
              className="
                mt-1.5 h-0.75 w-9
                rounded-full bg-[#24b715]
              "
            />
          </div>

          {/* VOIR TOUS LES PRODUITS */}
          <Link
            href={`/${currentLocale}/produits`}
            className="
              inline-flex items-center
              gap-1.5 text-[11px]
              font-bold text-[#168e0a]
              transition-colors
              hover:text-[#102b39]
              sm:text-sm
            "
          >
            {viewAllLabel}

            <ArrowRight
              size={16}
              aria-hidden="true"
            />
          </Link>
        </div>

        {/* GRILLE DES PRODUITS */}
        {selectedProducts.length > 0 ? (
          <div
            className="
              grid grid-cols-2 gap-2.5
              sm:gap-4
              lg:grid-cols-4
            "
          >
            {selectedProducts.map((product) => (
              <ProductCard
                key={product.id}
                product={product}
                locale={currentLocale}
              />
            ))}
          </div>
        ) : (
          <div
            className="
              rounded-xl border
              border-slate-200 bg-slate-50
              px-5 py-10 text-center
            "
          >
            <ShoppingCart
              size={28}
              className="mx-auto mb-3 text-slate-400"
              aria-hidden="true"
            />

            <p className="text-sm text-slate-600">
              {tr.empty}
            </p>
          </div>
        )}
      </div>
    </section>
  );
}

export default HomeProducts;

components/home/HomeReviews.tsx:
"use client";

import {
  useEffect,
  useState,
} from "react";

import {
  ChevronLeft,
  ChevronRight,
  MessageSquareQuote,
  Star,
  BadgeCheck,
} from "lucide-react";

import {
  resolveLocale,
  type SiteLocale,
} from "@/lib/site-i18n";

// =====================================================
// CYCLORIVA — AVIS CLIENTS DE LA PAGE D'ACCUEIL
// =====================================================
//
// Version PC et mobile fidèle à l'architecture.
//
// - Carte d'avis responsive
// - Étoiles vertes
// - Photo ou initiales du client
// - Flèches de navigation
// - Indicateurs de pagination
// - Cinq langues
// - Aucun avis fictif
// - Aucun avis vérifié sans preuve
//
// Les vrais avis peuvent être fournis au composant
// depuis une base de données ou une source fiable.
//
// =====================================================

// =====================================================
// TYPES
// =====================================================

export type HomeReview = {
  id: string;
  author: string;
  rating: number;
  comment: string;
  avatar?: string | null;
  date?: string;
  verified?: boolean;
};

export type HomeReviewsProps = {
  locale: SiteLocale;
  reviews?: HomeReview[];
  className?: string;
};

// =====================================================
// TRADUCTIONS
// =====================================================

type ReviewTexts = {
  heading: string;
  emptyTitle: string;
  emptyDescription: string;
  verified: string;
  previous: string;
  next: string;
  reviewNumber: string;
  rating: string;
};

const translations: Record<SiteLocale, ReviewTexts> = {
  fr: {
    heading: "Ce que nos clients disent de nous",
    emptyTitle: "Vos avis comptent",
    emptyDescription:
      "Les avis de nos clients seront publiés ici après leur collecte et leur vérification.",
    verified: "Client vérifié",
    previous: "Avis précédent",
    next: "Avis suivant",
    reviewNumber: "Afficher l'avis",
    rating: "Note",
  },

  en: {
    heading: "What our customers say about us",
    emptyTitle: "Your feedback matters",
    emptyDescription:
      "Customer reviews will appear here once they have been collected and verified.",
    verified: "Verified customer",
    previous: "Previous review",
    next: "Next review",
    reviewNumber: "Show review",
    rating: "Rating",
  },

  de: {
    heading: "Das sagen unsere Kunden über uns",
    emptyTitle: "Ihre Meinung zählt",
    emptyDescription:
      "Kundenbewertungen erscheinen hier, sobald sie gesammelt und geprüft wurden.",
    verified: "Verifizierter Kunde",
    previous: "Vorherige Bewertung",
    next: "Nächste Bewertung",
    reviewNumber: "Bewertung anzeigen",
    rating: "Bewertung",
  },

  it: {
    heading: "Cosa dicono i nostri clienti",
    emptyTitle: "La tua opinione conta",
    emptyDescription:
      "Le recensioni dei clienti appariranno qui dopo essere state raccolte e verificate.",
    verified: "Cliente verificato",
    previous: "Recensione precedente",
    next: "Recensione successiva",
    reviewNumber: "Mostra recensione",
    rating: "Valutazione",
  },

  es: {
    heading: "Lo que dicen nuestros clientes",
    emptyTitle: "Tu opinión cuenta",
    emptyDescription:
      "Las opiniones de nuestros clientes aparecerán aquí una vez recopiladas y verificadas.",
    verified: "Cliente verificado",
    previous: "Opinión anterior",
    next: "Opinión siguiente",
    reviewNumber: "Mostrar opinión",
    rating: "Valoración",
  },
};

// =====================================================
// OUTILS
// =====================================================

function clampRating(value: number): number {
  if (!Number.isFinite(value)) return 0;

  return Math.max(0, Math.min(5, Math.round(value)));
}

function getInitials(name: string): string {
  return name
    .trim()
    .split(/\s+/)
    .slice(0, 2)
    .map((part) => part.charAt(0))
    .join("")
    .toUpperCase();
}

function formatReviewDate(
  value: string,
  locale: SiteLocale
): string {
  const date = new Date(value);

  if (Number.isNaN(date.getTime())) {
    return "";
  }

  const localeMap: Record<SiteLocale, string> = {
    fr: "fr-FR",
    en: "en-IE",
    de: "de-DE",
    it: "it-IT",
    es: "es-ES",
  };

  return new Intl.DateTimeFormat(
    localeMap[locale],
    {
      year: "numeric",
      month: "short",
      day: "numeric",
      timeZone: "UTC",
    }
  ).format(date);
}

// =====================================================
// ÉTOILES DE NOTATION
// =====================================================

function ReviewStars({
  rating,
  label,
}: {
  rating: number;
  label: string;
}) {
  const normalizedRating = clampRating(rating);

  return (
    <div
      className="flex items-center gap-0.5 text-[#24b715]"
      role="img"
      aria-label={`${label} : ${normalizedRating}/5`}
    >
      {Array.from({ length: 5 }, (_, index) => (
        <Star
          key={index}
          size={16}
          strokeWidth={1.5}
          fill={
            index < normalizedRating
              ? "currentColor"
              : "none"
          }
          className={
            index < normalizedRating
              ? "text-[#24b715]"
              : "text-slate-300"
          }
          aria-hidden="true"
        />
      ))}
    </div>
  );
}

// =====================================================
// AVATAR CLIENT
// =====================================================

function ReviewAvatar({
  review,
}: {
  review: HomeReview;
}) {
  const [imageError, setImageError] = useState(false);

  const showImage = Boolean(
    review.avatar && !imageError
  );

  return (
    <div
      className="
        flex h-12 w-12 shrink-0
        items-center justify-center
        overflow-hidden rounded-full
        border border-slate-200
        bg-[#eaf8e7]
        text-sm font-extrabold text-[#102b39]
        sm:h-14 sm:w-14
      "
    >
      {showImage ? (
        <img
          src={review.avatar!}
          alt=""
          loading="lazy"
          onError={() => setImageError(true)}
          className="h-full w-full object-cover"
        />
      ) : (
        <span aria-hidden="true">
          {getInitials(review.author)}
        </span>
      )}
    </div>
  );
}

// =====================================================
// COMPOSANT PRINCIPAL
// =====================================================

export function HomeReviews({
  locale,
  reviews = [],
  className = "",
}: HomeReviewsProps) {
  const currentLocale = resolveLocale(locale);
  const tr = translations[currentLocale];

  const [activeIndex, setActiveIndex] = useState(0);

  const validReviews = reviews.filter(
    (review) =>
      Boolean(review.id.trim()) &&
      Boolean(review.author.trim()) &&
      Boolean(review.comment.trim()) &&
      Number.isFinite(review.rating) &&
      review.rating >= 1 &&
      review.rating <= 5
  );

  useEffect(() => {
    setActiveIndex(0);
  }, [reviews]);

  const totalReviews = validReviews.length;

  const safeIndex =
    totalReviews > 0
      ? activeIndex % totalReviews
      : 0;

  const activeReview =
    totalReviews > 0
      ? validReviews[safeIndex]
      : null;

  const showPrevious = () => {
    setActiveIndex((current) =>
      totalReviews > 0
        ? (current - 1 + totalReviews) %
          totalReviews
        : 0
    );
  };

  const showNext = () => {
    setActiveIndex((current) =>
      totalReviews > 0
        ? (current + 1) % totalReviews
        : 0
    );
  };

  return (
    <section
      id="home-reviews"
      aria-labelledby="home-reviews-title"
      className={`w-full bg-white py-5 sm:py-7 ${className}`}
    >
      <div className="w-full">

        {/* =========================================
            TITRE DE SECTION
        ========================================= */}

        <div className="mb-4">
          <h2
            id="home-reviews-title"
            className="
              text-xl font-extrabold
              tracking-tight text-[#102b39]
              sm:text-2xl
            "
          >
            {tr.heading}
          </h2>

          <div
            aria-hidden="true"
            className="
              mt-1.5 h-0.75 w-9
              rounded-full bg-[#24b715]
            "
          />
        </div>

        {/* =========================================
            AUCUN AVIS ENREGISTRÉ
        ========================================= */}

        {totalReviews === 0 ? (
          <div
            className="
              flex min-h-36 flex-col
              items-center justify-center
              rounded-xl border border-slate-200
              bg-white px-5 py-6
              text-center
            "
          >
            <MessageSquareQuote
              size={30}
              strokeWidth={1.5}
              className="mb-2 text-[#24b715]"
              aria-hidden="true"
            />

            <h3 className="text-sm font-bold text-[#102b39]">
              {tr.emptyTitle}
            </h3>

            <p
              className="
                mt-2 max-w-md
                text-xs leading-relaxed
                text-slate-600
              "
            >
              {tr.emptyDescription}
            </p>
          </div>
        ) : (
          <>
            {/* =====================================
                CARTE DE TÉMOIGNAGE
            ===================================== */}

            <div
              className="
                relative flex min-h-36
                items-center
                rounded-xl border
                border-slate-200 bg-white
                px-3 py-4 shadow-sm
                sm:px-5
              "
              aria-live="polite"
              aria-atomic="true"
            >
              {/* FLÈCHE PRÉCÉDENTE */}
              <button
                type="button"
                onClick={showPrevious}
                disabled={totalReviews <= 1}
                aria-label={tr.previous}
                className="
                  flex h-8 w-8 shrink-0
                  items-center justify-center
                  rounded-full border
                  border-slate-200 bg-white
                  text-[#102b39]
                  transition-colors
                  hover:bg-[#f2faef]
                  disabled:cursor-not-allowed
                  disabled:opacity-40
                "
              >
                <ChevronLeft
                  size={19}
                  aria-hidden="true"
                />
              </button>

              {/* CLIENT ET COMMENTAIRE */}
              {activeReview && (
                <div
                  key={activeReview.id}
                  className="
                    mx-3 flex min-w-0
                    flex-1 items-center
                    gap-3 sm:mx-5 sm:gap-4
                  "
                >
                  {/* PHOTO / INITIALES */}
                  <ReviewAvatar
                    review={activeReview}
                  />

                  {/* INFORMATIONS CLIENT */}
                  <div className="min-w-0 flex-1">

                    {/* ÉTOILES */}
                    <ReviewStars
                      rating={activeReview.rating}
                      label={tr.rating}
                    />

                    {/* COMMENTAIRE */}
                    <blockquote
                      className="
                        mt-1.5 line-clamp-4
                        text-[11px] italic
                        leading-relaxed
                        text-slate-700
                        sm:text-sm
                      "
                    >
                      “{activeReview.comment}”
                    </blockquote>

                    {/* NOM ET VÉRIFICATION */}
                    <div
                      className="
                        mt-2 flex flex-wrap
                        items-center gap-x-3
                        gap-y-1
                      "
                    >
                      <strong
                        className="
                          text-xs font-extrabold
                          text-[#102b39]
                          sm:text-sm
                        "
                      >
                        {activeReview.author}
                      </strong>

                      {activeReview.verified === true && (
                        <span
                          className="
                            inline-flex items-center
                            gap-1 text-[10px]
                            text-[#168e0a]
                          "
                        >
                          <BadgeCheck
                            size={14}
                            aria-hidden="true"
                          />

                          {tr.verified}
                        </span>
                      )}

                      {activeReview.date && (
                        <time
                          dateTime={activeReview.date}
                          className="text-[10px] text-slate-500"
                        >
                          {formatReviewDate(
                            activeReview.date,
                            currentLocale
                          )}
                        </time>
                      )}
                    </div>
                  </div>
                </div>
              )}

              {/* FLÈCHE SUIVANTE */}
              <button
                type="button"
                onClick={showNext}
                disabled={totalReviews <= 1}
                aria-label={tr.next}
                className="
                  flex h-8 w-8 shrink-0
                  items-center justify-center
                  rounded-full border
                  border-slate-200 bg-white
                  text-[#102b39]
                  transition-colors
                  hover:bg-[#f2faef]
                  disabled:cursor-not-allowed
                  disabled:opacity-40
                "
              >
                <ChevronRight
                  size={19}
                  aria-hidden="true"
                />
              </button>
            </div>

            {/* =====================================
                INDICATEURS DE NAVIGATION
            ===================================== */}

            {totalReviews > 1 && (
              <div
                className="
                  mt-3 flex items-center
                  justify-center gap-2
                "
                aria-label={tr.heading}
              >
                {validReviews.map((review, index) => (
                  <button
                    key={review.id}
                    type="button"
                    onClick={() => setActiveIndex(index)}
                    aria-label={`${tr.reviewNumber} ${
                      index + 1
                    }`}
                    aria-current={
                      safeIndex === index
                        ? "true"
                        : undefined
                    }
                    className={`
                      h-2 w-2 rounded-full
                      transition-all duration-200
                      ${
                        safeIndex === index
                          ? "bg-[#24b715]"
                          : "bg-slate-300 hover:bg-slate-400"
                      }
                    `}
                  />
                ))}
              </div>
            )}
          </>
        )}
      </div>
    </section>
  );
}

export default HomeReviews;

