                        h-6 w-6 text-[#24b715]
                        sm:h-8 sm:w-8
                      "
                    />
                  </div>

                  {/* TEXTE */}
                  <div className="min-w-0">
                    <h3
                      className="
                        text-[10px] font-extrabold
                        leading-tight text-[#102b39]
                        sm:text-xs
                        lg:text-sm
                      "
                    >
                      {translation.title}
                    </h3>

                    <p
                      className="
                        mt-1 text-[9px]
                        leading-snug text-slate-600
                        sm:text-[10px]
                        lg:text-xs
                      "
                    >
                      {translation.description}
                    </p>
                  </div>
                </div>
              );
            })}
          </div>

          {/* =======================================
              IMAGE OFFICIELLE
          ======================================= */}

          <div
            className="
              hidden overflow-hidden
              rounded-lg bg-[#f3f7f9]
              xl:block
            "
          >
            <img
              src="/images/accueil.png"
              alt={content.imageAlt}
              loading="lazy"
              decoding="async"
              width={660}
              height={260}
              className="
                h-32 w-full
                object-cover object-center
                transition-transform duration-300
                hover:scale-105
              "
            />
          </div>
        </div>
      </div>
    </section>
  );
}

export default HomeWhyChoose;

components/site/SiteFooter.tsx:
"use client";

import Link from "next/link";
import { informationPagePath } from "@/lib/site-routes";
import { useState, type FormEvent } from "react";
import { ArrowRight } from "lucide-react";

import {
  FaFacebookF,
  FaInstagram,
  FaYoutube,
  FaLinkedinIn,
} from "react-icons/fa6";

import { SiVisa, SiMastercard, SiPaypal } from "react-icons/si";

import { siteText, type SiteLocale, type SiteTextKey } from "@/lib/site-i18n";

type SiteFooterProps = {
  locale: SiteLocale;
};

type FooterItem = {
  key: SiteTextKey;
  href: string;
};

export function SiteFooter({ locale }: SiteFooterProps) {
  const [consent, setConsent] = useState(false);
  const [message, setMessage] = useState("");
  const [email, setEmail] = useState("");

  const tr = (key: SiteTextKey) => siteText(locale, key);

  const catalog = `/${locale}/produits`;

  const productSearch = (term: string) =>
    `${catalog}?q=${encodeURIComponent(term)}`;

  const storeLinks: FooterItem[] = [
    { key: "electric", href: productSearch("électrique") },
    { key: "mtb", href: productSearch("VTT") },
    { key: "cargo", href: productSearch("cargo") },
    { key: "city", href: productSearch("ville") },
    { key: "accessories", href: productSearch("accessoire") },
  ];

  const informationLinks: FooterItem[] = [
    { key: "about", href: informationPagePath(locale, "about") },
    { key: "guides", href: informationPagePath(locale, "guides") },
    { key: "customers", href: informationPagePath(locale, "customers") },
    { key: "delivery", href: informationPagePath(locale, "delivery") },
    { key: "returns", href: informationPagePath(locale, "returns") },
  ];

  const helpLinks: FooterItem[] = [
    { key: "faq", href: informationPagePath(locale, "faq") },
    { key: "warranty", href: informationPagePath(locale, "warranty") },
    { key: "payments", href: informationPagePath(locale, "payments") },
    { key: "track", href: informationPagePath(locale, "track") },
    { key: "contact", href: informationPagePath(locale, "contact") },
  ];

  const legalLinks: FooterItem[] = [
    { key: "legal", href: informationPagePath(locale, "legal") },
    { key: "privacy", href: informationPagePath(locale, "privacy") },
    { key: "terms", href: informationPagePath(locale, "terms") },
    { key: "cookies", href: informationPagePath(locale, "cookies") },
  ];

  function newsletterSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!consent) {
      setMessage(tr("newsletterNeedConsent"));
      return;
    }

    if (!email.trim()) {
      return;
    }

    // Le service d'inscription sera connecté ultérieurement.
    // Aucun email n'est enregistré pour le moment.
    setMessage(tr("newsletterPending"));
  }

  function renderFooterLinks(links: FooterItem[]) {
    return (
      <ul className="space-y-2 text-xs leading-5 text-slate-200">
        {links.map((item) => (
          <li key={item.key}>
            <Link
              href={item.href}
              className="transition-colors hover:text-[#75df40] focus-visible:text-[#75df40]"
            >
              {tr(item.key)}
            </Link>
          </li>
        ))}
      </ul>
    );
  }

  return (
    <footer className="w-full bg-[#102b39] text-white">
      <div className="w-full min-w-0 px-5 pb-5 pt-9 sm:px-8 lg:px-12">
        <div className="grid grid-cols-2 gap-x-6 gap-y-9 lg:grid-cols-[1.5fr_0.8fr_1fr_0.8fr_1.4fr_1.2fr] lg:gap-7">
          {/* LOGO ET PRÉSENTATION */}
          <div className="col-span-2 lg:col-span-1">
            <Link
              href={`/${locale}`}
              aria-label="CYCLORIVA"
              className="inline-flex items-center"
            >
              <span className="inline-flex rounded-md bg-white px-2 py-1">
                <img
                  src="/images/logo.png"
                  alt="CYCLORIVA"
                  width={215}
                  height={48}
                  className="h-11 w-auto max-w-53.75 object-contain object-left"
                />
              </span>
            </Link>

            <p className="mt-3 max-w-70 text-xs leading-5 text-slate-200">
              {tr("tagline")}
            </p>

            {/* RÉSEAUX SOCIAUX */}
            <div
              className="mt-5 flex items-center gap-5 text-white"
              aria-label={tr("networks")}
            >
              <span
                role="img"
                aria-label="Facebook"
                title="Facebook"
                className="inline-flex items-center"
              >
                <FaFacebookF size={19} />
              </span>

              <span
                role="img"
                aria-label="Instagram"
                title="Instagram"
                className="inline-flex items-center"
              >
                <FaInstagram size={19} />
              </span>

              <span
                role="img"
                aria-label="YouTube"
                title="YouTube"
                className="inline-flex items-center"
              >
                <FaYoutube size={19} />
              </span>

              <span
                role="img"
                aria-label="LinkedIn"
                title="LinkedIn"
                className="inline-flex items-center"
              >
                <FaLinkedinIn size={19} />
              </span>
            </div>
          </div>

          {/* BOUTIQUE */}
          <div>
            <h2 className="mb-4 text-sm font-bold">{tr("store")}</h2>
            {renderFooterLinks(storeLinks)}
          </div>

          {/* INFORMATIONS */}
          <div>
            <h2 className="mb-4 text-sm font-bold">{tr("information")}</h2>
            {renderFooterLinks(informationLinks)}
          </div>

          {/* AIDE */}
          <div>
            <h2 className="mb-4 text-sm font-bold">{tr("help")}</h2>
            {renderFooterLinks(helpLinks)}
          </div>

          {/* NEWSLETTER */}
          <div className="col-span-2 border-slate-500/50 lg:col-span-1 lg:border-l lg:pl-6">
            <h2 className="mb-4 text-sm font-bold">{tr("newsletter")}</h2>

            <form
              onSubmit={newsletterSubmit}
              className="flex min-w-0 overflow-hidden rounded-lg bg-white shadow-sm"
            >
              <input
                type="email"
                value={email}
                onChange={(event) => {
                  setEmail(event.target.value);
                  setMessage("");
                }}
                required
                autoComplete="email"
                aria-label={tr("email")}
                placeholder={tr("email")}
                className="min-w-0 flex-1 bg-white px-3 py-3 text-xs text-[#102b39] outline-none placeholder:text-slate-500"
              />

              <button
                type="submit"
                aria-label={tr("subscribe")}
                className="flex w-12 shrink-0 items-center justify-center bg-[#25b919] text-white transition-colors hover:bg-[#168e0a]"
              >
                <ArrowRight size={19} />
              </button>
            </form>

            <label className="mt-3 flex cursor-pointer items-start gap-2 text-[10px] leading-normal text-slate-200">
              <input
                type="checkbox"
                checked={consent}
                onChange={(event) => {
                  setConsent(event.target.checked);
                  setMessage("");
                }}
                className="mt-0.5 h-3.5 w-3.5 shrink-0 accent-[#30bd21]"
              />

              <span>{tr("newsletterConsent")}</span>
            </label>

            {message && (
              <p
                role="status"
                aria-live="polite"
                className="mt-3 rounded-md bg-white/10 px-3 py-2 text-[11px] leading-relaxed text-lime-200"
              >
                {message}
              </p>
            )}
          </div>

          {/* MOYENS DE PAIEMENT */}
          <div className="col-span-2 border-slate-500/50 lg:col-span-1 lg:border-l lg:pl-6">
            <h2 className="mb-4 text-sm font-bold">{tr("payment")}</h2>

            <div
              className="flex flex-wrap items-center gap-2"
              aria-label={tr("payment")}
            >
              <span
                title="Visa"
                aria-label="Visa"
                className="flex h-9 w-18 items-center justify-center rounded-md bg-white shadow-sm"
              >
                <SiVisa size={49} className="text-[#17328a]" />
              </span>

              <span
                title="Mastercard"
                aria-label="Mastercard"
                className="flex h-9 w-18 items-center justify-center rounded-md bg-white shadow-sm"
              >
                <SiMastercard size={42} className="text-[#e84c20]" />
              </span>

              <span
                title="PayPal"
                aria-label="PayPal"
                className="flex h-9 w-19.5 items-center justify-center gap-1 rounded-md bg-white shadow-sm"
              >
                <SiPaypal size={19} className="text-[#003087]" />

                <span className="text-[13px] font-extrabold italic tracking-tight text-[#003087]">
                  PayPal
                </span>
              </span>

              <span
                title="SEPA"
                aria-label="SEPA"
                className="flex h-9 w-18 items-center justify-center rounded-md bg-white text-[16px] font-black italic tracking-tight text-[#124286] shadow-sm"
              >
                SEPA
              </span>
            </div>

            <p className="mt-3 text-[10px] leading-4 text-slate-300">
              {tr("paymentPreview")}
            </p>
          </div>
        </div>

        {/* COPYRIGHT ET MENTIONS LÉGALES */}
        <div className="mt-9 flex flex-col gap-3 border-t border-slate-500/60 pt-5 text-[11px] leading-relaxed text-slate-300 md:flex-row md:items-center md:justify-between">
          <p>
            © {new Date().getFullYear()} CYCLORIVA. {tr("rights")}
          </p>

          <nav
            aria-label={tr("information")}
            className="flex flex-wrap items-center gap-x-3 gap-y-2"
          >
            {legalLinks.map((item, index) => (
              <span key={item.key} className="inline-flex items-center gap-3">
                {index > 0 && (
                  <span className="text-slate-500" aria-hidden="true">
                    |
                  </span>
                )}

                <Link
                  href={item.href}
                  className="text-slate-300 transition-colors hover:text-[#75df40] focus-visible:text-[#75df40]"
                >
                  {tr(item.key)}
                </Link>
              </span>
            ))}
          </nav>
        </div>
      </div>
    </footer>
  );
}

components/site/SiteHeader.tsx:
"use client";

import Link from "next/link";
import { ProductCartLink } from "@/components/product/ProductCartLink";
import { usePathname, useSearchParams } from "next/navigation";
import { useEffect, useRef, useState } from "react";
import {
  ChevronDown,
  ChevronRight,
  Heart,
  Menu,
  Search,
  UserRound,
  X,
  Tag,
  Home,
  Bike,
  Package,
  Mail,
} from "lucide-react";

import {
  siteLocales,
  siteText,
  type SiteLocale,
  type SiteTextKey,
} from "@/lib/site-i18n";

type NavigationItem = {
  key: SiteTextKey;
  href: (locale: SiteLocale) => string;
  icon: typeof Bike;
  submenu?: boolean;
};

type SiteHeaderProps = {
  locale: SiteLocale;
  languageUrl?: (locale: string) => string;
};

const productPath = (locale: SiteLocale, search?: string) => {
  const base = `/${locale}/produits`;

  if (!search) return base;

  return `${base}?q=${encodeURIComponent(search)}`;
};

const navigationItems: NavigationItem[] = [
  {
    key: "home",
    href: (locale) => `/${locale}`,
    icon: Home,
  },
  {
    key: "electric",
    href: (locale) => productPath(locale, "électrique"),
    icon: Bike,
    submenu: true,
  },
  {
    key: "mtb",
    href: (locale) => productPath(locale, "VTT"),
    icon: Bike,
    submenu: true,
  },
  {
    key: "cargo",
    href: (locale) => productPath(locale, "cargo"),
    icon: Bike,
    submenu: true,
  },
  {
    key: "city",
    href: (locale) => productPath(locale, "ville"),
    icon: Bike,
    submenu: true,
  },
  {
    key: "accessories",
    href: (locale) => productPath(locale, "accessoire"),
    icon: Package,
    submenu: true,
  },
  {
    key: "brands",
    href: (locale) => productPath(locale),
    icon: Bike,
    submenu: true,
  },
  {
    key: "promotions",
    href: (locale) => productPath(locale),
    icon: Tag,
  },
  {
    key: "contact",
    href: (locale) => `/${locale}/contact`,
    icon: Mail,
  },
];

export function SiteHeader({
  locale,
  languageUrl,
}: SiteHeaderProps) {
  const pathname = usePathname();
  const searchParams = useSearchParams();

  const [drawerOpen, setDrawerOpen] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);

  const drawerRef = useRef<HTMLElement>(null);
  const menuButtonRef = useRef<HTMLButtonElement>(null);

  const tr = (key: SiteTextKey) => siteText(locale, key);

  const currentPath = pathname ?? `/${locale}`;
  const isHomePage = currentPath.replace(/\/+$/, "") === `/${locale}`;

  const getLanguageUrl = (language: SiteLocale) => {
    if (languageUrl) {
      return languageUrl(language);
    }

    const segments = currentPath.split("/");

    if (segments.length > 1) {
      segments[1] = language;
    }

    const nextPath = segments.join("/");
    const query = searchParams.toString();

    return query ? `${nextPath}?${query}` : nextPath;
  };

  // Fermer les menus lors du changement de page.
  useEffect(() => {
    const frame = requestAnimationFrame(() => { setDrawerOpen(false); setSearchOpen(false); });
    return () => cancelAnimationFrame(frame);
  }, [pathname]);

  // Gérer la fermeture du menu et le défilement mobile.
  useEffect(() => {
    if (!drawerOpen) return;

    const menuButton = menuButtonRef.current;
    const previousOverflow = document.body.style.overflow;
    const previouslyFocused = document.activeElement;

    document.body.style.overflow = "hidden";

    const focusable = drawerRef.current?.querySelectorAll<HTMLElement>(
      'a[href], button:not([disabled]), input:not([disabled]), [tabindex]:not([tabindex="-1"])'
    );

    focusable?.[0]?.focus();

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setDrawerOpen(false);
      }

      if (event.key === "Tab") {
        const elements = drawerRef.current?.querySelectorAll<HTMLElement>(
          'a[href], button:not([disabled]), input:not([disabled]), [tabindex]:not([tabindex="-1"])'
        );

        if (!elements || elements.length === 0) return;

        const first = elements[0];
        const last = elements[elements.length - 1];

        if (event.shiftKey && document.activeElement === first) {
          event.preventDefault();
          last.focus();
        } else if (
          !event.shiftKey &&
          document.activeElement === last
        ) {
          event.preventDefault();
          first.focus();
        }
      }
    };

    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener("keydown", handleKeyDown);

      if (previouslyFocused instanceof HTMLElement) {
        previouslyFocused.focus();
      } else {
        menuButton?.focus();
      }
    };
  }, [drawerOpen]);

  const languageLinks = (
    <nav
      aria-label={tr("languages")}
      className="flex items-center justify-center gap-1 text-[12px] font-semibold text-[#102b39]"
    >
      {siteLocales.map((language, index) => (
        <span
          key={language}
          className="inline-flex items-center gap-1"
        >
          <Link
            href={getLanguageUrl(language)}
            lang={language}
            aria-current={
              locale === language ? "page" : undefined
            }
            onClick={() => setDrawerOpen(false)}
            className={`rounded-full px-2 py-1 transition-colors ${
              locale === language
                ? "bg-[#ddf6d6] text-[#168b11]"
                : "hover:bg-slate-100"
            }`}
          >
            {language.toUpperCase()}
          </Link>

          {index < siteLocales.length - 1 && (
            <span
              className="text-slate-300"
              aria-hidden="true"
            >
              |
            </span>
          )}
        </span>
      ))}
    </nav>
  );

  return (
    <>
      <header className="relative z-40 w-full border-b border-slate-200 bg-white text-[#102b39] shadow-sm">
        {/* =========================================
            VERSION PC : EN-TÊTE PRINCIPAL
        ========================================= */}

        <div className="hidden h-19 w-full min-w-0 items-center gap-7 px-7 lg:flex xl:px-12">
          {/* LOGO OFFICIEL */}
          <Link
            href={`/${locale}`}
            className="shrink-0"
            aria-label="CYCLORIVA"
          >
            <img
              src="/images/logo.png"
              alt="CYCLORIVA"
              className="h-12 w-auto max-w-71.25 object-contain"
            />
          </Link>

          {/* RECHERCHE PC */}
          <form
            action={`/${locale}/produits`}
            method="GET"
            role="search"
            className="mx-auto flex h-11 min-w-0 max-w-122.5 flex-1 items-center overflow-hidden rounded-xl border border-slate-300 bg-white shadow-sm focus-within:border-[#2ebc18]"
          >
            <Search
              size={18}
              className="ml-4 shrink-0 text-slate-500"
            />

            <input
              type="search"
              name="q"
              aria-label={tr("searchButton")}
              placeholder={tr("search")}
              className="min-w-0 flex-1 bg-transparent px-3 text-sm text-[#102b39] outline-none"
            />

            <button
              type="submit"
              aria-label={tr("searchButton")}
              className="flex h-full w-14 items-center justify-center bg-[#24b715] text-white transition-colors hover:bg-[#159707]"
            >
              <Search size={20} />
            </button>
          </form>

          {/* LANGUES PC */}
          {languageLinks}

          {/* ACTIONS PC */}
          <div className="flex shrink-0 items-center gap-4">
            <button
              type="button"
              disabled
              title={tr("soon")}
              aria-label={`${tr("account")} — ${tr("soon")}`}
              className="opacity-60"
            >
              <UserRound size={23} />
            </button>

            <Link href={"/" + locale + "/favoris"} aria-label={tr("favorites")}><Heart size={24} /></Link>

            <ProductCartLink locale={locale} />
          </div>
        </div>

        {/* =========================================
            VERSION PC : MENU HORIZONTAL
        ========================================= */}

        <nav
          aria-label={tr("menu")}
          className="hidden h-13.25 w-full min-w-0 items-center justify-between gap-1 overflow-x-auto border-t border-slate-100 px-7 lg:flex xl:gap-3 xl:px-12"
        >
          {navigationItems.map((item) => (
            <Link
              key={item.key}
              href={item.href(locale)}
              aria-current={item.key === "home" && isHomePage ? "page" : undefined}
              className={`inline-flex h-9 shrink-0 items-center gap-1.5 rounded-md px-3 text-[13px] font-bold transition-colors ${
                item.key === "home" && isHomePage
                  ? "bg-[#24b715] text-white"
                  : item.key === "promotions"
                    ? "text-[#16a007] hover:bg-green-50"
                    : "hover:bg-slate-100"
              }`}
            >
              {item.key === "promotions" && (
                <Tag size={15} />
              )}

              <span>{tr(item.key)}</span>

              {item.submenu && (
                <ChevronDown size={13} aria-hidden="true" />
              )}
            </Link>
          ))}
        </nav>

        {/* =========================================
            VERSION MOBILE : EN-TÊTE
        ========================================= */}

        <div className="flex h-17.25 items-center gap-2 px-3 sm:px-5 lg:hidden">
          {/* BOUTON MENU */}
          <button
            ref={menuButtonRef}
            type="button"
            aria-label={tr("menu")}
            aria-expanded={drawerOpen}
            aria-controls="cycloriva-mobile-menu"
            onClick={() => setDrawerOpen(true)}
            className="rounded-md p-1.5 hover:bg-slate-100"
          >
            <Menu size={27} />
          </button>

          {/* LOGO */}
          <Link
            href={`/${locale}`}
            className="min-w-0 flex-1"
            aria-label="CYCLORIVA"
          >
            <img
              src="/images/logo.png"
              alt="CYCLORIVA"
              className="h-9.25 w-auto max-w-47.5 object-contain object-left sm:max-w-57.5"
            />
          </Link>

          {/* RECHERCHE */}
          <button
            type="button"
            aria-label={tr("searchButton")}
            aria-expanded={searchOpen}
            onClick={() => setSearchOpen((open) => !open)}
            className="rounded-md p-1.5 hover:bg-slate-100"
          >
            <Search size={22} />
          </button>

          {/* COMPTE */}
          <button
            type="button"
            disabled
            title={tr("soon")}
            aria-label={`${tr("account")} — ${tr("soon")}`}
            className="rounded-md p-1 opacity-60"
          >
            <UserRound size={21} />
          </button>

          {/* PANIER */}
          <ProductCartLink locale={locale} />
        </div>

        {/* LANGUES MOBILE */}
        <div className="flex h-11 items-center justify-center border-t border-slate-100 lg:hidden">
          {languageLinks}
        </div>

        {/* RECHERCHE MOBILE DÉPLIABLE */}
        {searchOpen && (
          <form
            action={`/${locale}/produits`}
            method="GET"
            role="search"
            className="flex gap-2 border-t border-slate-100 p-3 lg:hidden"
          >
            <input
              type="search"
              name="q"
              aria-label={tr("searchButton")}
              placeholder={tr("search")}
              autoFocus
              className="min-w-0 flex-1 rounded-md border border-slate-300 px-3 py-2 text-sm outline-none focus:border-[#24b715]"
            />

            <button
              type="submit"
              aria-label={tr("searchButton")}
              className="rounded-md bg-[#24b715] px-4 text-white"
            >
              <Search size={19} />
            </button>
          </form>
        )}
      </header>

      {/* =========================================
          MENU LATÉRAL MOBILE
      ========================================= */}

      {drawerOpen && (
        <div
          id="cycloriva-mobile-menu"
          className="fixed inset-0 z-100 lg:hidden"
        >
          {/* FOND SOMBRE */}
          <button
            type="button"
            className="absolute inset-0 bg-[#071827]/60"
            aria-label={tr("close")}
            onClick={() => setDrawerOpen(false)}
          />

          {/* PANNEAU DU MENU */}
          <aside
            ref={drawerRef}
            role="dialog"
            aria-modal="true"
            aria-label={tr("menu")}
